    ('system-design', 'Slow payment provider takes down the site', 'Retrying each slow payment call immediately on another thread, taken from a separate backup pool', 'Retrying each slow payment call immediately on another thread'),
    ('system-design', 'Retried payment charges the card twice', 'Disable retries so users must tap the button again themselves after a timeout', 'Disable retries so users must tap the button again themselves'),
    ('system-design', 'Retried payment charges the card twice', 'Make the timeout much longer so that automatic retries happen less often', 'Make the timeout longer so retries happen less often'),
