    ('system-design', 'Feed pages repeat and skip items', 'Block new posts from appearing while any user is paginating through the feed', 'Block new posts from appearing while any user is paginating'),
    ('system-design', 'Feed pages repeat and skip items', 'Switch to cursor-based pagination anchored to the last item seen, not a numeric offset', 'Switch to cursor-based pagination anchored to the last item seen instead of a numeric offset'),
    ('system-design', 'Feed pages repeat and skip items', 'Increase the page size so fewer pages are needed and fewer items shift', 'Increase the page size so fewer pages are needed'),
    ('system-design', 'Feed pages repeat and skip items', 'Sort the feed randomly so that duplicates are less noticeable to users', 'Sort the feed randomly so duplicates are less noticeable'),
    ('system-design', 'Rate limit that still allows bursts', 'Use a strict fixed interval of one request every 600 milliseconds for each client', 'Use a strict fixed interval of one request every 600 milliseconds'),
    ('system-design', 'Rate limit that still allows bursts', 'No rate limit at all, since the bursts come from legitimate clients and should never be rejected', 'No rate limit, since bursts are legitimate'),
    ('system-design', 'Every release is all-or-nothing', 'Add a mandatory two-week manual QA cycle before every single deploy to catch bad releases early', 'Add a mandatory two-week manual QA cycle before every deploy'),
    ('system-design', 'Every release is all-or-nothing', 'Deploy to all servers at once, but keep a finger on the rollback button throughout every deploy', 'Deploy to all servers at once but keep a finger on the rollback button'),
    ('system-design', 'Every release is all-or-nothing', 'Canary releases: send a small share of traffic to the new version, widening it if healthy', 'Canary releases: send a small percentage of traffic to the new version and widen gradually if healthy'),
    ('system-design', 'Which of six services made it slow?', 'More detailed logging inside each of the services, still without any correlation IDs between them', 'More detailed logging inside each service, still without correlation IDs'),
    ('system-design', 'Which of six services made it slow?', 'Merging the six services into a single service so that there is only one log file to search', 'Merging the six services into one so there is only one log'),
    ('system-design', 'Which of six services made it slow?', 'A shared spreadsheet where every team pastes its log timestamps for each slow request it sees', 'A shared spreadsheet where teams paste their log timestamps'),
    ('system-design', 'Testing a rewrite without risking users', 'Write more unit tests until the team''s confidence is high enough to ship', 'Write more unit tests until confidence is high enough'),
    ('system-design', 'Testing a rewrite without risking users', 'Mirror production traffic to the new engine in shadow mode and compare its outputs', 'Mirror production traffic to the new engine in shadow mode and compare its outputs to the old one'),
    ('system-design', 'Testing a rewrite without risking users', 'Deploy it to all users at once and monitor closely for incoming pricing complaints', 'Deploy it to all users and monitor closely for pricing complaints'),
    ('system-design', 'Logged out but the token still works', 'Store the JWT in two separate cookies instead of one, so a thief would need to steal both of them', 'Store the JWT in two cookies instead of one for extra safety'),
    ('system-design', 'Logged out but the token still works', 'Use short-lived access tokens with revocable refresh tokens, so revocation applies in minutes', 'Use short-lived access tokens with revocable refresh tokens, so revocation takes effect within minutes'),
    ('system-design', 'Logged out but the token still works', 'Extend the JWT lifetime so that users need to log in less often, which reduces token exposure', 'Extend the JWT lifetime so users need to log in less often')
) AS changes (category_slug, question_title, old_text, new_text)
JOIN categories ON categories.slug = changes.category_slug
JOIN questions
    ON questions.category_id = categories.id
    AND questions.title = changes.question_title
WHERE question_options.question_id = questions.id
    AND question_options.option_text = changes.old_text;

COMMIT;
